#include <stdio.h>
#define MIN_AGE 1
#define MAX_AGE 125
#define ADULT 18
#define SENIOR 65
#define CHILD_FARE 13.45
#define ADULT_FARE 21.95
#define SENIOR_FARE 18.95
int main( void ) {
    int age;
    double fare;
    printf( "Please enter your age: " );
    scanf( "%d", &age );
    while( age < MIN_AGE || age > MAX_AGE ) {
        printf( "Error: age entered is not valid.\n" );
        printf( "Please enter your age: " );
        scanf( "%d", &age );
    }
    if( age < ADULT )
        fare = CHILD_FARE;
    else if( age < SENIOR )
        fare = ADULT_FARE;
    else
        fare = SENIOR_FARE;
    printf( "Cost of tour ticket: $%.2f\n", fare );
    return 0;
}

#include <stdio.h>
#include <math.h>
#define THRESHOLD 1.0e-6
int main( void ) {
    double nextNumerator;
    double sum = 0.0;
    double x;
    int n = 1;
    printf( "Please enter value of x (0 < x < 2): " );
    scanf( "%lf", &x );
    nextNumerator = x - 1.0;
    while( fabs( nextNumerator / n ) >= THRESHOLD ) {
        sum += nextNumerator / n;
        nextNumerator = -( x - 1.0 ) * nextNumerator;
        n++;
    }
    printf( "Approximation to ln(%f) is %f\n", x, sum );
    printf( "- computed using %d terms.\n", n - 1 );
    return 0;
}

#include <stdio.h>
int main( void ) {
    int num1, num2;
    int max;
    int min;
    printf( "Please enter a sequence of pairs of positive integers.\n"
            "Terminate by entering at least one non-positive value\n"
            "in a pair.\n" );
    scanf( "%d %d", &num1, &num2 );
    max = num1;
    min = num2;
    while( num1 > 0 && num2 > 0 ) {
        if( num1 > max )
            max = num1;
        if( num2 < min )
            min = num2;
        scanf( "%d %d", &num1, &num2 );
    }
    printf( "Max of first numbers: %d\n", max );
    printf( "Min of second numbers: %d\n", min );
    return 0;
}

#include <stdio.h>
#define DATA_FILE "data.txt"
#define NUM_PER_ROW 100
int main( void ) {
    double sum;
    int count;
    double next;
    double average;
    FILE* inFile;
    inFile = fopen( DATA_FILE, "r" );
    if( inFile == NULL )
        printf( "Error opening file. Program terminating...\n" );
    else {
        while( fscanf( inFile, "%lf", &next ) == 1 ) {
            sum = next;
            count = 1;
            while( count < NUM_PER_ROW ) {
                fscanf( inFile, "%lf", &next );
                sum += next;
                count++;
            }
            average = sum / count;
            printf( "%.3lf\n", average );
        }
        fclose( inFile );
    }
    return 0;
}
